  function attributeInputs(prefix,properties,fields=[]){const keys=[...new Set([...Object.keys(properties||{}),...fields.map(f=>f.name)])];return keys.map((key,i)=>{const v=properties?.[key],field=fields.find(f=>f.name===key),type=field?.type||(typeof v==='boolean'?'boolean':typeof v==='number'?'number':'string'),id=prefix+'-'+i,label=esc(key)+(field?.unit?' ('+esc(field.unit)+')':'');return '<label for="'+id+'">'+label+'</label>'+(type==='boolean'?'<select id="'+id+'" data-attr-name="'+esc(key)+'" data-attr-type="boolean">'+options({'':'Keine Angabe',true:'Ja',false:'Nein'},v==null?'':String(v))+'</select>':'<input id="'+id+'" data-attr-name="'+esc(key)+'" data-attr-type="'+type+'" type="'+(type==='number'?'number':'text')+'" step="any" value="'+esc(v??'')+'">');}).join('')||'<p class="wb-note">Noch keine Attribute. Über „Attributfeld hinzufügen“ eigene Felder anlegen.</p>';}
  function readAttributes(parent){const attrs={};for(const input of parent.querySelectorAll('[data-attr-name]')){const k=input.dataset.attrName,t=input.dataset.attrType,v=input.value;attrs[k]=t==='number'?(v===''?null:Number(v)):t==='boolean'?(v===''?null:v==='true'):v;}return attrs;}
  function coordinateRows(points){return '<div class="wb-coordinate-scroll"><table class="wb-table wb-coordinate-table"><thead><tr><th>Nr.</th><th>X / Ost (m)</th><th>Y / Nord (m)</th><th>Z absolut (m)</th><th></th></tr></thead><tbody>'+points.map((c,i)=>'<tr><td>'+(i+1)+'</td>'+[0,1,2].map(k=>'<td><input data-coordinate="'+i+':'+k+'" type="number" step="any" value="'+esc(c[k]??'')+'" '+(k<2?'required':'placeholder="Gelände"')+' aria-label="Punkt '+(i+1)+' '+['X','Y','Z'][k]+'"></td>').join('')+'<td><button type="button" class="text-button" data-remove-vertex="'+i+'" aria-label="Punkt '+(i+1)+' entfernen">×</button></td></tr>').join('')+'</tbody></table></div>';}
