  function coordinateDialog(){const e=active(),f=e?.object.features.find(f=>f.id===featureId);locked(e);if(!f)return;let cs=C.clone(f.type==='Point'?[f.coordinates]:f.coordinates);dialog('Stützpunkte bearbeiten','<p class="field-help">'+esc(P().reference.horizontal)+' · '+esc(W.verticals[P().reference.vertical])+'. Leeres Z folgt dem Gelände. Änderungen werden gemeinsam geprüft.</p><form id="wb-coordinates-form"><div id="wb-coordinate-rows"></div><div class="wb-actions"><button id="wb-vertex-add" type="button" class="button">+ Stützpunkt</button><button class="button primary">Koordinaten übernehmen</button></div></form>');const paint=()=>{$('wb-coordinate-rows').innerHTML=coordinateRows(cs);$('wb-coordinate-rows').querySelectorAll('[data-remove-vertex]').forEach(b=>b.onclick=guard(()=>{cs=readCoordinateRows($('wb-coordinate-rows'));cs.splice(Number(b.dataset.removeVertex),1);paint();}));};paint();$('wb-vertex-add').hidden=f.type==='Point';event('wb-vertex-add','click',()=>{cs=readCoordinateRows($('wb-coordinate-rows'));cs.push(cs.length?[...cs.at(-1)]:[0,0,null]);paint();});event('wb-coordinates-form','submit',ev=>{ev.preventDefault();cs=readCoordinateRows($('wb-coordinate-rows'));change('Stützpunkte bearbeitet: '+f.id,p=>{const e=W.find(p,activeKey);locked(e);e.object.features.find(q=>q.id===f.id).coordinates=f.type==='Point'?cs[0]:cs;});$('wb-dialog').close();});}
