  document.querySelector('.workspace').insertAdjacentHTML('beforeend','<aside class="wb-right" aria-label="Eigenschaften und Werkzeuge"><div class="wb-right-head"><span class="eyebrow">PROJEKTWERKZEUGE</span><h2 id="wb-panel-title">Layer-Eigenschaften</h2></div><div class="wb-tabs" role="group" aria-label="Werkzeugbereich"><button data-wb-tab="layer" class="active">Layer</button><button data-wb-tab="edit">Objekte</button><button data-wb-tab="measure">Messen</button><button data-wb-tab="quality">Prüfen</button></div><div id="wb-panel" class="wb-panel"></div></aside>');
