  document.body.insertAdjacentHTML('beforeend','<dialog id="wb-dialog" class="wb-dialog"><div class="dialog-header"><div><span id="wb-dialog-eyebrow" class="eyebrow">GEOLAB WORKSPACE</span><h2 id="wb-dialog-title"></h2></div><button id="wb-dialog-close" class="icon-button" aria-label="Dialog schließen">×</button></div><div id="wb-dialog-content" class="dialog-content"></div></dialog>');
  function dialog(title,html){$('wb-dialog-title').textContent=title;$('wb-dialog-content').innerHTML=html;if(!$('wb-dialog').open)$('wb-dialog').showModal();}
