    $('wb-panel').innerHTML='<h3>'+esc(o.name||o.id)+'</h3><p class="wb-note">'+esc(W.kinds[e.type])+' · '+esc(e.id)+'</p>'+(e.type==='bodies'?'<p class="wb-note">'+esc(o.facies||'')+'<br>'+esc(o.phase||'')+'</p><button id="wb-geology-concept" class="button">Geologisches Konzept & Quellen</button>':'')+'<form id="wb-layer-form" class="wb-form">'+field('wb-layer-name','Name',o.name||o.id)+field('wb-layer-group','Gruppe',w.group)+(e.type!=='terrain'&&e.type!=='boreholes'?field('wb-layer-color','Farbe',o.color||'#508d8e','color'):'')+(e.type==='gisLayers'?'<label for="wb-color-field">Farbe nach Attribut (Kategorien)</label><select id="wb-color-field"><option value="">Einheitliche Layerfarbe</option>'+colorFields.map(k=>'<option value="'+esc(k)+'" '+(o.symbology?.field===k?'selected':'')+'>'+esc(k)+'</option>').join('')+'</select>':'')+(e.type!=='boreholes'?field('wb-layer-opacity','Deckkraft (%)',Math.round((o.opacity??1)*100),'number','min="0" max="100" step="1"'):'')+'<label for="wb-layer-status">Datenart / Aussage</label><select id="wb-layer-status">'+options({'beobachtet':'Beobachtet','interpretiert':'Interpretiert','modelliert':'Modelliert','synthetisch':'Synthetisch'},w.status)+'</select>'+field('wb-layer-source','Quelle / Herkunft',w.source)+field('wb-layer-uncertainty','Dokumentierte Lageunsicherheit (m, leer = unbekannt)',w.uncertainty_m??'','number','min="0" step="any"')+'<details class="wb-advanced"><summary>Eigene Layerattribute</summary><label for="wb-layer-attributes">Zusätzliche Metadaten (JSON)</label><textarea id="wb-layer-attributes">'+esc(JSON.stringify(o.properties||{},null,2))+'</textarea></details>'+'<label class="wb-inline"><input id="wb-layer-lock" type="checkbox" '+(w.locked?'checked':'')+'> Geometrie gegen Bearbeitung sperren</label><button class="button primary">Eigenschaften übernehmen</button></form><div class="wb-actions"><button id="wb-layer-table" class="button">Attributtabelle</button><button id="wb-layer-remove" class="button danger">Layer entfernen</button>'+(e.type==='gisLayers'?'<button id="wb-layer-copy" class="button">Layer duplizieren</button>':'')+'</div><h3 class="wb-subheading">RAUMBEZUG</h3><p class="wb-note">'+esc(W.systems[P().reference.horizontal].name)+' · '+esc(P().reference.horizontal)+'<br>'+esc(W.verticals[P().reference.vertical])+'<br>Einheit: Meter · Koordinaten im Projektgitter</p>'+(['layers','bodies'].includes(e.type)?'<button id="wb-volume" class="button">Körpervolumen berechnen</button><div id="wb-volume-result"></div>':'')+(e.type==='boreholes'?'<button id="wb-bore-show" class="button">Bohrprofil anzeigen</button>':'')+'<h3 class="wb-subheading">ANSICHTEN</h3><div class="wb-actions"><button id="wb-bookmark-save" class="button">Ansicht merken</button><button id="wb-bookmarks" class="button">Ansichten öffnen</button></div>';
    event('wb-layer-form','submit',ev=>{ev.preventDefault();const vals={name:$('wb-layer-name').value.trim(),group:$('wb-layer-group').value.trim(),status:$('wb-layer-status').value,source:$('wb-layer-source').value,locked:$('wb-layer-lock').checked,uncertainty:$('wb-layer-uncertainty').value,color:$('wb-layer-color')?.value,opacity:$('wb-layer-opacity')?.value};const props=JSON.parse($('wb-layer-attributes').value);validateProperties(props,[]);if(!vals.name)throw new Error('Bitte einen Namen eingeben.');change('Layer-Eigenschaften: '+vals.name,p=>{const o=W.find(p,activeKey).object;o.name=vals.name;o.properties=props;if(vals.color)o.color=vals.color;if(vals.opacity!==undefined)o.opacity=Number(vals.opacity)/100;if(e.type==='gisLayers'){const key=$('wb-color-field')?.value||'';if(key){const values=[...new Set(o.features.map(f=>String(f.properties?.[key])))].sort(),categories=Object.fromEntries(values.map((v,i)=>[v,C.palette[i%C.palette.length]]));o.symbology={field:key,categories};}else delete o.symbology;}o.workspace={...o.workspace,group:vals.group||W.kinds[e.type],status:vals.status,source:vals.source,locked:vals.locked,uncertainty_m:vals.uncertainty===''?null:Number(vals.uncertainty)};});});
    event('wb-layer-table','click',()=>{dock='attributes';renderDock();});
