    $('wb-panel').innerHTML='<h3>'+esc(l.name)+'</h3>'+(isLocked?'<div class="wb-callout">Dieser Layer ist gegen Geometrie- und Attributänderungen gesperrt.</div>':'')+'<div class="wb-actions"><button id="wb-new-feature" class="button" '+(isLocked?'disabled':'')+'>+ Objekt numerisch</button><button id="wb-draw-feature" class="button" '+(isLocked?'disabled':'')+'>In Karte zeichnen</button><button id="wb-edit-table" class="button">Tabelle</button><button id="wb-select-map" class="button">Rechteckauswahl</button></div>'+(f?'<div class="wb-feature-chip">Objekt '+esc(f.id)+' · '+esc(f.type)+'</div><form id="wb-feature-form" class="wb-form"><button type="button" id="wb-coordinate-edit" class="button" '+(isLocked?'disabled':'')+'>Stützpunkte numerisch bearbeiten</button><div id="wb-object-attributes" class="wb-form">'+attributeInputs('wb-feature-prop',f.properties||{},l.fields||[])+'</div><button class="button primary" '+(isLocked?'disabled':'')+'>Objektänderungen übernehmen</button></form><div class="wb-actions"><button id="wb-feature-measure" class="button">Geometrie messen</button><button id="wb-feature-transform" class="button" '+(isLocked?'disabled':'')+'>Verschieben / Drehen</button><button id="wb-feature-delete" class="button danger" '+(isLocked?'disabled':'')+'>Objekt entfernen</button></div>':'<p class="wb-note">Wähle ein Objekt in der Attributtabelle oder in der 2D-Karte aus. Neue Geometrien lassen sich exakt über Zahlen eingeben oder mit Fangfunktion digitalisieren.</p>')+'<h3 class="wb-subheading">ATTRIBUTSTRUKTUR</h3><p class="wb-note">'+(l.fields||[]).map(a=>esc(a.name)+' · '+esc(a.type)+(a.unit?' ('+esc(a.unit)+')':'')).join('<br>')+'</p><button id="wb-field-add" class="button" '+(isLocked?'disabled':'')+'>Attributfeld hinzufügen</button><h3 class="wb-subheading">FANGEN IN DER KARTE</h3><div class="wb-form"><label class="wb-inline"><input id="wb-snap-enabled" type="checkbox" checked> An Punkten und Kanten fangen</label>'+field('wb-snap-tolerance','Toleranz in Projektmetern',10,'number','min="0" step="any"')+'</div><p class="wb-note">Erfasst sichtbare GIS-Objekte und Bohransatzpunkte. Freie Kartenklicks sind digitalisierte Positionen; genaue Messungen verwenden Originalstützpunkte oder numerische Eingaben.</p>';
    event('wb-create-gis','click',newLayer);event('wb-edit-table','click',()=>{dock='attributes';renderDock();});
    event('wb-select-map','click',()=>{boxSelecting=true;setMapMode('split');$('wb-map-tip').hidden=false;$('wb-map-tip').textContent='Rechteck aufziehen: Wählt schneidende Objekte des aktiven GIS-Layers. Danach mit den Attributen weiterarbeiten.';});event('wb-new-feature','click',()=>featureDialog(false));event('wb-draw-feature','click',()=>featureDialog(true));
    event('wb-coordinate-edit','click',coordinateDialog);if(isLocked)$('wb-object-attributes')?.querySelectorAll('input,select').forEach(i=>i.disabled=true);event('wb-feature-form','submit',ev=>{ev.preventDefault();const coordinates=C.clone(f.coordinates),properties=readAttributes($('wb-object-attributes'));validateProperties(properties,l.fields||[]);change('Objekt bearbeitet: '+f.id,p=>{const e=W.find(p,activeKey);locked(e);const target=e.object.features.find(q=>q.id===f.id);target.coordinates=coordinates;target.properties=properties;});});
    event('wb-feature-delete','click',async()=>{if(await A.confirmAction('Objekt entfernen?','Das Objekt wird aus diesem Layer entfernt. Rückgängig ist in dieser Sitzung verfügbar.'))change('Objekt entfernt: '+f.id,p=>{const e=W.find(p,activeKey);locked(e);e.object.features=e.object.features.filter(q=>q.id!==f.id);});});
